function d(t,r){return t*r}function m(t){return t.reduce((r,o)=>r+(o.total??Number(o.cantidad)*Number(o.precio_unitario)),0)}function f(t,r=.18){return t*r}function b(t,r={}){const{porcentajeOverhead:o=0,aplicarITBIS:u=!1}=r,e=Number(m(t))||0,n=Number(o)||0,s=e*(n/100),c=e+s,a=u?f(c):0,l=c+a;return{subtotal:e,costoOverhead:s,baseITBIS:c,montoITBIS:a,total:l,porcentajeOverhead:o,aplicarITBIS:u}}function N(t){const r=Number(t);return isNaN(r)?"RD$ 0.00":`RD$ ${r.toLocaleString("es-DO",{minimumFractionDigits:2,maximumFractionDigits:2})}`}function I(t,r,o,u){const{total:e}=b(t,{porcentajeOverhead:o,aplicarITBIS:u});let n=0;t.forEach(a=>{if(!a.estructura)return;r.filter(i=>i.estructura===a.estructura).forEach(i=>{n+=(Number(a.cantidad)||1)*Number(i.precio)})});const s=n*(o/100),c=n+s;return e+c}export{I as c,N as f,b as r,d as t};
